// The releases the rule generator can load.
//
// website/static/generator/profiles/versions.json is generated by
// bin/generate-versions.sh from profiles/. The rules are embedded in it, so
// the page needs one request and keeps working from file://.
//
// No network access here beyond that same-origin file.

export const VERSIONS_FILE = "./profiles/versions.json";

/** Entries worth showing: a version label and at least one rule. */
export function isUsableVersion(entry) {
  return Boolean(
    entry
      && typeof entry.value === "string"
      && entry.value.trim()
      && Array.isArray(entry.rules)
      && entry.rules.length > 0,
  );
}

export function findVersion(versions, value) {
  if (!Array.isArray(versions)) return null;
  const wanted = String(value ?? "").trim();
  if (!wanted) return null;
  return versions.find((entry) => entry.value === wanted) || null;
}

/**
 * One line for the picker: the release, whether it is the current one, and
 * where its rules came from — so a loaded stamp is never a mystery.
 */
export function describeVersion(entry) {
  if (!isUsableVersion(entry)) return "";
  const note = entry.note && entry.note !== "older release" ? ` — ${entry.note}` : "";
  const source = entry.source ? ` (${entry.source})` : "";
  return `${entry.label || entry.value}${note}${source}`;
}

/** Load the manifest. Throws when it cannot be read; callers decide. */
export async function loadVersions() {
  const response = await fetch(VERSIONS_FILE, { cache: "no-cache" });
  if (!response.ok) throw new Error(`${VERSIONS_FILE}: HTTP ${response.status}`);
  const data = await response.json();
  const versions = Array.isArray(data?.versions) ? data.versions.filter(isUsableVersion) : [];
  if (versions.length === 0) throw new Error(`${VERSIONS_FILE}: no usable versions`);
  return {
    current: String(data.current || ""),
    versions,
  };
}
